public void tick() {
        super.tick();
        if (this.isDeadOrDying()){
            this.stopAnimations();
        }
        if (this.level.isClientSide){
            if (this.isAlive()){
                if (!this.isStartingUp() && !this.isShuttingDown()){
                    if (!this.isActivated()){
                        this.stopMostAnimations(this.offAnimationState);
                        this.offAnimationState.startIfStopped(this.tickCount);
                    } else {
                        if (!this.isMeleeAttacking()) {
                            this.attackAnimationState.stop();
                            if (this.isMoving()) {
                                this.stopMostAnimations(this.walkAnimationState);
                                this.walkAnimationState.startIfStopped(this.tickCount);
                            } else {
                                if (this.isNovelty){
                                    this.stopMostAnimations(this.alertAnimationState);
                                    this.alertAnimationState.startIfStopped(this.tickCount);
                                } else {
                                    this.stopMostAnimations(this.idleAnimationState);
                                    this.idleAnimationState.startIfStopped(this.tickCount);
                                }
                            }
                        } else if (this.isMeleeAttacking()) {
                            ++this.attackTick;
                        }
                    }
                } else if (this.isStartingUp()){
                    this.stopMostAnimations(this.activateAnimationState);
                    this.activateAnimationState.startIfStopped(this.tickCount);
                } else if (this.isShuttingDown()){
                    this.stopMostAnimations(this.deactivateAnimationState);
                    this.deactivateAnimationState.startIfStopped(this.tickCount);
                }
            }
        }
        if (!this.level.isClientSide) {
            if (this.isAlive()){
                if (this.isStartingUp() || this.isActivated()) {
                    if (this.tickCount % 7 == 0) {
                        if (!this.isAggressive()) {
                            this.playSound(ModSounds.SQUALL_GOLEM_WIND_SLOW.get());
                        } else {
                            this.playSound(ModSounds.SQUALL_GOLEM_WIND_FAST.get());
                        }
                    }
                }
                if (this.isProximity()){
                    LivingEntity livingEntity = null;
                    for (LivingEntity living : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox()
                            .inflate(6))){
                        if (MobUtil.isOwnedTargetable(this, living) && living.hasLineOfSight(this)){
                            livingEntity = living;
                        }
                    }
                    if (livingEntity != null || this.getTarget() != null){
                        this.activeTime = 100;
                    }
                }
                if (this.requiresPower()) {
                    if (this.activeTime > 0) {
                        --this.activeTime;
                        if (!this.isStartingUp() && !this.isActivated()) {
                            this.setStartingUp(true);
                            this.level.broadcastEntityEvent(this, (byte) 25);
                        }
                    } else if (this.getBoundPos() != null && !this.reachedHome){
                        this.setTarget(null);
                        ++this.homeTick;
                        if (this.getNavigation().isStableDestination(this.boundPos)){
                            this.getNavigation().moveTo(this.boundPos.getX() + 0.5D, this.boundPos.getY(), this.boundPos.getZ() + 0.5D, 1.0D);
                            if (this.homeTick >= MathHelper.secondsToTicks(10)){
                                this.homeTick = 0;
                                this.reachedHome = true;
                            } else if (this.boundPos.closerToCenterThan(this.position(), this.getBbWidth() + 1.0D)){
                                this.moveTo(this.boundPos.above(), this.getYRot(), this.getXRot());
                                this.reachedHome = true;
                            }
                        } else {
                            this.reachedHome = true;
                        }
                    } else {
                        if (!this.isShuttingDown() && this.isActivated()) {
                            this.getNavigation().stop();
                            this.setShuttingDown(true);
                            this.level.broadcastEntityEvent(this, (byte) 26);
                        }
                    }
                }
                if (this.isStartingUp() && !this.isActivated()){
                    this.getNavigation().stop();
                    this.reachedHome = false;
                    ++this.startingUpTick;
                    if (this.startingUpTick == 1){
                        this.playSound(ModSounds.SQUALL_GOLEM_ACTIVATE.get(), 2.0F, 1.0F);
                        this.playSound(ModSounds.SQUALL_GOLEM_WIND_START.get());
                    }
                    if (this.startingUpTick >= MathHelper.secondsToTicks(2.6F)){
                        this.setStartingUp(false);
                        this.level.broadcastEntityEvent(this, (byte) 27);
                        this.setActivated(true);
                        this.level.broadcastEntityEvent(this, (byte) 29);
                        this.startingUpTick = 0;
                    }
                } else if (this.isShuttingDown() && this.isActivated()){
                    this.getNavigation().stop();
                    ++this.shuttingDownTick;
                    if (this.shuttingDownTick == 1){
                        this.playSound(ModSounds.SQUALL_GOLEM_DEACTIVATE.get(), 2.0F, 1.0F);
                        this.playSound(ModSounds.SQUALL_GOLEM_WIND_START.get());
                    }
                    if (this.shuttingDownTick >= MathHelper.secondsToTicks(3.625F)){
                        this.setShuttingDown(false);
                        this.level.broadcastEntityEvent(this, (byte) 28);
                        this.setActivated(false);
                        this.level.broadcastEntityEvent(this, (byte) 30);
                        this.shuttingDownTick = 0;
                        this.reachedHome = false;
                    }
                }
                if (!this.isStartingUp() && !this.isShuttingDown()) {
                    if (this.isMeleeAttacking()) {
                        ++this.attackTick;
                    }
                    if (this.isActivated() && !this.isMeleeAttacking() && !this.isMoving()) {
                        ++this.idleTime;
                        if (this.level.random.nextFloat() <= 0.05F && this.hurtTime <= 0 && (this.getTarget() == null || this.getTarget().isDeadOrDying()) && !this.isNovelty && this.idleTime >= MathHelper.secondsToTicks(10)) {
                            this.idleTime = 0;
                            this.isNovelty = true;
                            this.level.broadcastEntityEvent(this, (byte) 22);
                        }
                    } else {
                        this.isNovelty = false;
                        this.level.broadcastEntityEvent(this, (byte) 23);
                    }
                    if (this.isNovelty){
                        ++noveltyTick;
                        this.level.broadcastEntityEvent(this, (byte) 24);
                        if (this.noveltyTick >= 150 || this.getTarget() != null || this.hurtTime > 0){
                            this.isNovelty = false;
                            this.noveltyTick = 0;
                            this.level.broadcastEntityEvent(this, (byte) 23);
                        }
                    }
                }
            }
        }
    }

public void tick() {
        if (hackComplete) return;

        isStarted = true;

        if (stopWormTimer > 0) {
            stopWormTimer--;
        }
        if (nukeVirusCooldown > 0) {
            nukeVirusCooldown--;
        }

        allConnections.clear();
        int nonNullNodes = 0;
        int completeNodes = 0;
        for (int i = 0; i < nodes.length; i++) {
            Node node = getNodeAt(i);
            if (node == null) continue;
            nonNullNodes++;

            int f = node.fortification;
            node.tick();
            if (controller != null && f < NODE_FORTIFICATION_TIME && node.fortification == NODE_FORTIFICATION_TIME) {
                controller.onNodeFortified(this, i);
            }

            if (side == HackingSide.AI && isAwake() && (isDummy() || node.isHacked()) && node.outGoingHacks.isEmpty()) {
                // start the trace to all neighbouring nodes
                for (int neighbourPos : getNeighbours(i)) {
                    Node neighbourNode = getNodeAt(neighbourPos);
                    if (neighbourNode != null && (isDummy() || !neighbourNode.isHacked())) {
                        // found an unhacked neighbour
                        node.startHacking(i, neighbourPos);
                    }
                }
            }

            if (pendingNukePos == i) {
                activateNukeVirus(i);
            }

            // update all in-progress connections
            int finishedConns = 0;
            for (Pair<Integer, Float> conn : node.outGoingHacks) {
                if (conn.getValue() < 1F) {
                    if (stopWormTimer == 0) {
                        Node targetNode = getNodeAt(conn.getKey());
                        if (targetNode != null) {
                            conn.setValue(Math.min(1F, conn.getValue() + targetNode.getProgressPerTick()));
                            targetNode.setHackProgress(conn.getKey(), conn.getValue(), true);
                        }
                    }
                } else {
                    finishedConns++;
                }
                allConnections.add(new ConnectionEntry(i, conn.getKey(), conn.getValue()));
            }
            if (finishedConns == node.outGoingHacks.size() && !node.outGoingHacks.isEmpty()) completeNodes++;
        }
        if (completeNodes >= nonNullNodes) {
            hackComplete = true;
        }
    }

public boolean initiateNukeVirus(int pos) {
        Validate.isTrue(pos >= 0 && pos < GRID_SIZE, "nuke position " + pos + " out of range!");
        Node node = getNodeAt(pos);
        if (node != null && pendingNukePos < 0 && isNukeVirusReady()
                && node.type != NetworkComponentType.DIAGNOSTIC_SUBROUTINE
                && node.type != NetworkComponentType.NETWORK_REGISTRY)
        {
            pendingNukePos = pos;
            return true;
        } else {
            return false;
        }
    }

public void activateNukeVirus(int pos) {
        int neighbour = getHackedNeighbour(pendingNukePos);
        if (neighbour >= 0) {
            boolean found = false;
            Node neighbourNode = getNodeAt(neighbour);
            if (neighbourNode != null) {
                for (Pair<Integer, Float> conn : neighbourNode.outGoingHacks) {
                    if (conn.getLeft() == pendingNukePos) {
                        conn.setValue(1f);
                        found = true;
                    }
                }
                if (!found) {
                    neighbourNode.outGoingHacks.add(Pair.of(pendingNukePos, 1f));
                }
                Node node = getNodeAt(pos);
                if (node != null) {
                    node.setHackProgress(pos, 1f, false);
                }
                if (controller != null) controller.getHacker().playSound(SoundEvents.GENERIC_EXPLODE.value(), 1f, 1f);
                nukeVirusCooldown = 60;
            }
        }
        pendingNukePos = -1;
    }

public void setHackProgress(int pos, float hackProgress, boolean notifyController) {
            boolean wasHacked = isHacked();
            this.hackProgress = hackProgress;
            if (controller != null && isHacked() && !wasHacked) {
                if (isStarted) {
                    if (side == HackingSide.AI && isAwake()) {
                        controller.getHacker().playSound(SoundEvents.NOTE_BLOCK_BASEDRUM.value(), 1f, 1f);
                    } else if (side == HackingSide.PLAYER) {
                        controller.getHacker().playSound(SoundEvents.NOTE_BLOCK_FLUTE.value(), 1f, 1f);
                    }
                }
                if (notifyController) controller.onNodeHacked(HackSimulation.this, pos);
                if (isStarted && targets.contains(this.type)) {
                    hackComplete = true;  // hacked a target node: game over!
                }
            }
        }

void startHacking(int fromPos, int toPos) {
            outGoingHacks.add(MutablePair.of(toPos, 0F));
            if (controller != null) controller.onConnectionStarted(HackSimulation.this, fromPos, toPos, 0F);
        }

@Override
    public void tick() {
        if (te.isRemoved() || !hacker.isAlive()) {
            // TODO maybe find a way to catch up with hackers who disconnect just to avoid getting zapped?
            return;
        }

        boolean wasDone = isSimulationDone();

        if (!(hacker.containerMenu instanceof SecurityStationHackingMenu) && !playerSimulation.isHackComplete()) {
            // hacker closed their window before hack complete: AI wins
            for (int slot = 0; slot < HackSimulation.GRID_SIZE; slot++) {
                HackSimulation.Node node = aiSimulation.getNodeAt(slot);
                if (node != null && node.getType() == NetworkComponentType.NETWORK_IO_PORT) {
                    node.setHackProgress(slot, 1F, true);
                    break;
                }
            }
        } else if (!wasDone) {
            playerSimulation.tick();
            aiSimulation.tick();
        }

        boolean syncToClient = (te.nonNullLevel().getGameTime() & 0x7) == 0;
        if (!wasDone && aiSimulation.isHackComplete()) {
            // security station wins
            syncToClient = true;
            if (aiSimulation.isAwake()) {
                // if hack window is closed before AI detects intrustion, hacker gets away with it
                if (te.nonNullLevel().isClientSide) {
                    hacker.playSound(SoundEvents.ENDERMAN_DEATH, 1f, 1f);
                } else {
                    hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackFailed.1").withStyle(ChatFormatting.RED), false);
                    if (!justTesting) {
                        hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackFailed.2").withStyle(ChatFormatting.RED), false);
                        te.retaliate(hacker);
                    }
                }
            }
        } else if (!wasDone && playerSimulation.isHackComplete()) {
            // hacker wins
            syncToClient = true;
            if (te.nonNullLevel().isClientSide) {
                hacker.playSound(SoundEvents.PLAYER_LEVELUP, 1f, 1f);
            } else {
                hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackSucceeded.1").withStyle(ChatFormatting.GREEN), false);
                if (!justTesting) {
                    hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackSucceeded.2").withStyle(ChatFormatting.GREEN), false);
                    te.addHacker(hacker.getGameProfile());
                }
            }
        }
        if (!te.nonNullLevel().isClientSide() && syncToClient) {
            NetworkHandler.sendToPlayer(PacketSyncHackSimulationUpdate.forSecurityStation(te), (ServerPlayer) hacker);
        }
    }

